import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * G11 / plan 6.1 point 1: the Premium device key is a SecureStore entry, so Android must keep
 * the `SecureStore` shared-preferences file out of Auto Backup (Android 11 and lower) and out of
 * the Android 12+ cloud backup and device transfer. This only READS the generated manifest and
 * the rules files expo-secure-store ships; it changes nothing (the manifest is generated by
 * `npm run prebuild:android`, never edited by hand).
 */

const ROOT = join(__dirname, '../../..');
const read = (path: string) => readFileSync(join(ROOT, path), 'utf8');

const MANIFEST = read('android/app/src/main/AndroidManifest.xml');
const RULES_DIR = 'node_modules/expo-secure-store/android/src/main/res/xml';
const KOTLIN = read(
  'node_modules/expo-secure-store/android/src/main/java/expo/modules/securestore/SecureStoreModule.kt'
);

describe('Android backup rules keep the SecureStore preferences out', () => {
  it('points the generated manifest at expo-secure-store rules for both Android generations', () => {
    expect(MANIFEST).toContain('android:fullBackupContent="@xml/secure_store_backup_rules"');
    expect(MANIFEST).toContain(
      'android:dataExtractionRules="@xml/secure_store_data_extraction_rules"'
    );
  });

  it('names the same preferences file the module writes', () => {
    expect(KOTLIN).toMatch(/SHARED_PREFERENCES_NAME\s*=\s*"SecureStore"/);
  });

  it('excludes it from Android 11 and lower Auto Backup', () => {
    const rules = read(`${RULES_DIR}/secure_store_backup_rules.xml`);

    expect(rules).toContain('<exclude domain="sharedpref" path="SecureStore"/>');
  });

  it('excludes it from the Android 12+ cloud backup and from device transfer', () => {
    const rules = read(`${RULES_DIR}/secure_store_data_extraction_rules.xml`);
    const cloud = rules.match(/<cloud-backup>[\s\S]*?<\/cloud-backup>/)?.[0] ?? '';
    const transfer = rules.match(/<device-transfer>[\s\S]*?<\/device-transfer>/)?.[0] ?? '';

    expect(cloud).toContain('<exclude domain="sharedpref" path="SecureStore"/>');
    expect(transfer).toContain('<exclude domain="sharedpref" path="SecureStore"/>');
  });
});
